mapper.update:
UPDATE rooms
SET status = #{status}, updated_at = NOW()
WHERE room_id = #{roomId}

mapper.select:
SELECT * FROM rooms


        accommodation_id = #{accommodationId}


        AND room_type = #{roomType}


        AND capacity >= #{minCapacity}


        AND price_per_night <= #{maxPrice}


        AND status = #{status}

SELECT r.* FROM rooms r
JOIN accommodations a ON r.accommodation_id = a.accommodation_id
WHERE a.host_id = #{hostId}

SELECT r.room_id, r.accommodation_id, r.name, r.description, r.price_per_night, r.original_price, r.discount_rate, r.cancellation_policy, r.capacity, r.room_count, -- 객실의 총 보유량 r.room_type, r.bed_type, r.bathroom_count, r.amenities, r.status, r.created_at, r.updated_at -- min_available_count 컬럼은 서비스 레이어에서 계산 후 채워짐 FROM rooms r WHERE r.accommodation_id = #{accommodationId}
AND r.capacity >= #{guestCount}
AND r.status IN ('ACTIVE', 'AVAILABLE')
ORDER BY r.price_per_night ASC, r.name ASC
